add_filter( 'woocommerce_sale_flash', 'perfectpixel_sale_badge_text', 10, 3 );

function perfectpixel_sale_badge_text( $html, $post, $product ) {
	$text = trim( '{{sale_badge_text}}' );
	if ( '' === $text ) {
		return '';
	}
	$percent = '';
	if ( $product && $product->is_type( 'simple' ) && (float) $product->get_regular_price() > 0 ) {
		$percent = '-' . round( 100 - (float) $product->get_sale_price() / (float) $product->get_regular_price() * 100 ) . '%';
	}
	return '<span class="onsale">' . esc_html( trim( str_replace( '{percent}', $percent, $text ) ) ) . '</span>';
}
